public class CircuitBreaker {
    enum State { CLOSED, OPEN, HALF_OPEN }
    private State state = State.CLOSED;
    private int failureCount = 0;
    private final int failureThreshold;
    private long openedAt = 0;
    private final long openDurationMs;

    public CircuitBreaker(int failureThreshold, long openDurationMs) {
        this.failureThreshold = failureThreshold;
        this.openDurationMs = openDurationMs;
    }

    public void recordFailure() {
        failureCount++;
        if (failureCount >= failureThreshold) {
            state = State.OPEN;
            openedAt = System.currentTimeMillis();
        }
    }

    public void recordSuccess() {
        failureCount = 0;
        state = State.CLOSED;
    }

    public boolean allowRequest() {
        if (state == State.CLOSED) return true;
        if (state == State.OPEN) {
            if (System.currentTimeMillis() - openedAt >= openDurationMs) {
                state = State.HALF_OPEN;
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN
    }

    public State getState() { return state; }

    public static void main(String[] args) throws InterruptedException {
        CircuitBreaker cb = new CircuitBreaker(3, 2000);
        cb.recordFailure(); cb.recordFailure(); cb.recordFailure();
        System.out.println("After 3 failures: " + cb.getState());
        System.out.println("Request allowed: " + cb.allowRequest());
        Thread.sleep(2100);
        System.out.println("After delay, request allowed: " + cb.allowRequest());
        System.out.println("State: " + cb.getState());
        cb.recordSuccess();
        System.out.println("After success: " + cb.getState());
    }
}

