import java.util.Random;
import java.util.concurrent.Callable;

public class RetryWithBackoff {
    private static final Random rng = new Random();

    static String execute(Callable<String> task, int maxAttempts) {
        Exception last = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return task.call();
            } catch (Exception e) {
                last = e;
                if (attempt < maxAttempts) {
                    long delay = Math.min(100L * (1L << (attempt - 1)), 400) + rng.nextInt(50);
                    try { Thread.sleep(delay); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
                }
            }
        }
        throw new RuntimeException("All " + maxAttempts + " attempts failed", last);
    }

    public static void main(String[] args) {
        int[] calls = {0};
        String result = execute(() -> {
            calls[0]++;
            if (calls[0] < 3) throw new RuntimeException("Transient failure");
            return "success";
        }, 3);
        System.out.println(result); // success

        try {
            execute(() -> { throw new RuntimeException("Always fails"); }, 3);
        } catch (RuntimeException e) {
            System.out.println("RuntimeException: " + e.getMessage());
        }
    }
}
